/// UserContent mirrors aimux-core/src/message.rs.
public indirect enum UserContent: Codable, Equatable, Sendable {
    case text(String)
    case parts([UserContentPart])

    public init(from d: Decoder) throws {
        let c = try d.singleValueContainer()
        if let v = try? c.decode(String.self) { self = .text(v); return }
        if let v = try? c.decode([UserContentPart].self) { self = .parts(v); return }
        throw DecodingError.dataCorruptedError(in: c, debugDescription: "UserContent: no variant matches")
    }

    public func encode(to e: Encoder) throws {
        var c = e.singleValueContainer()
        switch self {
        case .text(let v): try c.encode(v)
        case .parts(let v): try c.encode(v)
        }
    }
}

