        try c.encodeIfPresent(resolution, forKey: .resolution)
        try c.encodeIfPresent(duration, forKey: .duration)
        try c.encodeIfPresent(fps, forKey: .fps)
        try c.encodeIfPresent(seed, forKey: .seed)
