        case "compatibility": self = .compatibility(try WarningCompatibility(from: d))
        case "deprecated": self = .deprecated(try WarningDeprecated(from: d))
        case "other": self = .other(try WarningOther(from: d))
        default: throw DecodingError.dataCorrupted(.init(codingPath: d.codingPath, debugDescription: "Warning: unknown tag \(tag)"))
