            try v.encode(to: e)
            var t = e.container(keyedBy: AnyCodingKey.self)
            try t.encode("unsupported", forKey: AnyCodingKey("type"))
        case .compatibility(let v):
            try v.encode(to: e)
            var t = e.container(keyedBy: AnyCodingKey.self)
            try t.encode("compatibility", forKey: AnyCodingKey("type"))
        case .deprecated(let v):
            try v.encode(to: e)
            var t = e.container(keyedBy: AnyCodingKey.self)
            try t.encode("deprecated", forKey: AnyCodingKey("type"))
        case .other(let v):
            try v.encode(to: e)
            var t = e.container(keyedBy: AnyCodingKey.self)
            try t.encode("other", forKey: AnyCodingKey("type"))
